return ['domain'=>'zinn-translate','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'ne_NP','project-id-version'=>'zinn-translate','pot-creation-date'=>'2026-10-01T19:55:52+00:00','po-revision-date'=>'2026-10-01T19:55:52+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Translate'=>'Zinn® Translate','https://zinndigital.com/wordpress-plugins/zinn-translate'=>'https://zinndigital.com/wordpress-plugins/zinn-translate','Publishes this site in every language you choose, on its own web addresses, with translated slugs, metadata, menus, WooCommerce products, hreflang, per-language sitemaps and llms.txt. Translate with your Zinn Digital® plan or with your own provider key.'=>'यस साइटलाई तपाईंले रोज्नुभएको हरेक भाषामा, आफ्नै वेब ठेगानाहरूमा, अनुवाद गरिएका स्लगहरू, मेटाडेटा, मेनुहरू, WooCommerce उत्पादनहरू, hreflang, भाषा अनुसारका साइटम्यापहरू र llms.txt सहित प्रकाशित गर्दछ। तपाईंको Zinn Digital® योजना वा तपाईंको आफ्नै प्रदायक कुञ्जी मार्फत अनुवाद गर्नुहोस्।','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Stored. Type a new value to replace it.'=>'भण्डारण गरियो। यसलाई बदल्न नयाँ मान टाइप गर्नुहोस्।','Filter this list…'=>'यो सूची फिल्टर गर्नुहोस्…','Filter this list'=>'यो सूची फिल्टर गर्नुहोस्','Nothing matches that filter.'=>'त्यो फिल्टरसँग केही पनि मेल खाँदैन।','Add a row'=>'पङ्क्ति थप्नुहोस्','Remove this row'=>'यो पङ्क्ति हटाउनुहोस्','Remove'=>'हटाउनुहोस्','Zinn Digital®'=>'Zinn Digital®','Zinn Digital® — overview'=>'Zinn Digital® — अवलोकन','Overview'=>'सिंहावलोकन','Copied'=>'प्रतिलिपि गरियो','Every Zinn® plugin on this site, and whether it is working.'=>'यो साइटमा भएको प्रत्येक Zinn® प्लगइन, र यो काम गरिरहेको छ कि छैन।','No connection is needed for this plugin.'=>'यो प्लगइनको लागि कुनै जडान आवश्यक पर्दैन।','Open settings'=>'सेटिङहरू खोल्नुहोस्','You do not have permission to change these settings.'=>'तपाईंसँग यी सेटिङहरू परिवर्तन गर्ने अनुमति छैन।','Settings